package com.muxigame.city;
import java.util.*;
import net.minecraft.client.gui.*;
import net.minecraft.client.gui.components.*;
import net.minecraft.client.gui.screens.*;
import net.minecraft.nbt.*;
import net.minecraft.network.chat.Component;
import net.neoforged.neoforge.network.PacketDistributor;

/** Administrative planning only. Live city ledgers remain on the server. */
public final class CityWorksScreen extends Screen {
 CompoundTag data;int tab,fileIndex,personIndex,houseIndex,typeIndex,turns;boolean mirror;String resource="minecraft:oak_planks",local="";EditBox name,x,y,z,quantity,cityPrice,wealth;String draftName="新建筑",dx="",dy="",dz="";
 private final CityNpcSetupScreen setupReturn; CityNpcSetupScreen setupParent(){return setupReturn;}
 public CityWorksScreen(CompoundTag t){this(t,null);} public CityWorksScreen(CompoundTag t,CityNpcSetupScreen back){super(Component.literal("城市建设与维护"));data=t;tab=t.getInt("Tab");setupReturn=back;}
 public void onClose(){if(setupReturn!=null)setupReturn.resume();else super.onClose();}
 public void update(CompoundTag t){stash();data=t;tab=t.getInt("Tab");rebuildWidgets();}
 void stash(){if(tab==2&&name!=null){draftName=name.getValue();dx=x.getValue();dy=y.getValue();dz=z.getValue();}}
 Button button(String s,int x,int y,int w,Runnable task){return addRenderableWidget(Button.builder(Component.literal(s),b->task.run()).bounds(x,y,w,20).build());}
 EditBox edit(String value,int x,int y,int w){var e=addRenderableWidget(new EditBox(font,x,y,w,18,Component.literal(value)));e.setMaxLength(64);e.setValue(value);return e;}
 void send(String op,int a,int b,int c,int state,String value,boolean flag){try{PacketDistributor.sendToServer(new CityNetwork.Request(op,data.getString("Id"),data.getLong("Revision"),a,b,c,tab,0,state,value,flag));}catch(Exception ex){local="请检查输入格式";}}
 void send(String op,String value){send(op,0,0,0,0,value,false);}
 CompoundTag person(){var list=data.getList("People",Tag.TAG_COMPOUND);return list.isEmpty()?new CompoundTag():list.getCompound(Math.floorMod(personIndex,list.size()));}
 CompoundTag house(){var list=data.getList("Houses",Tag.TAG_COMPOUND);return list.isEmpty()?new CompoundTag():list.getCompound(Math.floorMod(houseIndex,list.size()));}
 protected void init(){String[] tabs={"维护概况","工坊与工匠","施工蓝图","公仓与报价"};for(int i=0;i<4;i++){int n=i;button((tab==i?"✓ ":"")+tabs[i],12+i*(width-24)/4,32,(width-30)/4,()->{stash();tab=n;rebuildWidgets();});}
  if(tab==0){button(data.getBoolean("Finalized")?"城市已首次定稿":"首次城市定稿…",16,72,width-32,()->{if(data.getBoolean("Finalized"))return;minecraft.setScreen(new ConfirmScreen(ok->{minecraft.setScreen(this);if(ok)send("works_finalize","");},Component.literal("按现在的地形和房屋定稿？"),Component.literal("以后维护以此为准；不会恢复建城前挖掉的山。请先完成初始建筑登记。")));});button(data.getBoolean("Enabled")?"自主维护：开启":"自主维护：暂停",16,100,width-32,()->send("works_pause",""));button("导出方块豁免与状态分类表",16,128,width-32,()->send("works_rules",""));}
  else if(tab==1){button("工坊："+house().getString("Name")+" · "+house().getString("Type"),16,72,width-32,()->{houseIndex++;rebuildWidgets();});button("居民："+person().getString("Name"),16,100,width-32,()->{personIndex++;rebuildWidgets();});button("将此居民登记为该工坊的修复工匠",16,130,width-32,()->send("works_artisan",person().getString("Id")+"|"+house().getString("Id")));}
  else if(tab==2){var files=data.getList("Files",Tag.TAG_STRING);String selected=files.isEmpty()?"":files.getString(Math.floorMod(fileIndex,files.size()));button("建筑档案："+(selected.isEmpty()?"还没有NBT档案":selected),16,64,width-32,()->{stash();fileIndex++;rebuildWidgets();});name=edit(draftName,100,92,width-116);button("用途："+CityRegistry.TYPES.get(typeIndex),16,119,150,()->{stash();typeIndex=(typeIndex+1)%CityRegistry.TYPES.size();rebuildWidgets();});button("房主："+person().getString("Name"),174,119,width-190,()->{stash();personIndex++;rebuildWidgets();});x=edit(dx.isEmpty()?""+data.getInt("X"):dx,40,148,100);y=edit(dy.isEmpty()?""+data.getInt("Y"):dy,170,148,90);z=edit(dz.isEmpty()?""+data.getInt("Z"):dz,290,148,100);button("旋转："+turns*90+"°",16,175,150,()->{stash();turns=(turns+1)%4;rebuildWidgets();});button(mirror?"左右镜像：开":"左右镜像：关",174,175,width-190,()->{stash();mirror=!mirror;rebuildWidgets();});button("生成施工投影",16,203,150,()->{try{stash();send("works_preview",Integer.parseInt(x.getValue()),Integer.parseInt(y.getValue()),Integer.parseInt(z.getValue()),turns,selected+"|"+name.getValue()+"|"+CityRegistry.TYPES.get(typeIndex)+"|"+person().getString("Id"),mirror);}catch(Exception ex){local="坐标请填整数";}});button("确认下达蓝图…",174,203,width-190,()->minecraft.setScreen(new ConfirmScreen(ok->{minecraft.setScreen(this);if(ok)send("works_build",data.getString("Ticket"));},Component.literal("确认施工位置与房主？"),Component.literal("工匠会逐渐建设，私人房主支付材料费。")))).active=data.contains("Ticket");button("取消选中未竣工蓝图…",16,232,width-32,()->minecraft.setScreen(new ConfirmScreen(ok->{minecraft.setScreen(this);if(ok)send("works_cancel",house().getString("Id"));},Component.literal("取消："+house().getString("Name")+"？"),Component.literal("已经施工的部分标记为烂尾，空闲工匠最后拆除。"))));button("选择项目："+house().getString("Name")+" · "+house().getString("Stage"),16,258,width-32,()->{stash();houseIndex++;rebuildWidgets();});}
  else{button("公共资源："+new net.minecraft.world.item.ItemStack(CityEconomy.item(resource)).getHoverName().getString(),16,65,width-32,()->minecraft.setScreen(new CityItemPicker(this,id->{resource=id;minecraft.setScreen(this);})));quantity=edit("10",120,95,90);button("从背包存入",16,123,150,()->{try{send("works_deposit",Integer.parseInt(quantity.getValue()),0,0,0,resource,false);}catch(Exception ex){local="数量须整数";}});button("实际取回背包",174,123,width-190,()->{try{send("works_withdraw",Integer.parseInt(quantity.getValue()),0,0,0,resource,false);}catch(Exception ex){local="数量须整数";}});cityPrice=edit(""+data.getInt("CityPrice"),120,168,90);wealth=edit(""+data.getInt("WealthRatio"),120,195,90);button("保存城乡报价预览参数",224,168,width-240,()->{try{send("works_prices",Integer.parseInt(cityPrice.getValue()),Integer.parseInt(wealth.getValue()),0,0,"",false);}catch(Exception ex){local="倍率请填写整数百分比";}});}
  button("刷新",16,height-28,90,()->send("works_view",""));button("返回现场",width-116,height-28,100,this::onClose);
 }
 public void render(GuiGraphics g,int mx,int my,float partial){g.fill(0,0,width,height,0xff18252a);g.drawString(font,"城市建设与维护 · "+data.getString("Name"),16,12,0xffffdd99);if(tab==0){int y=160;String[] lines={"建筑血量 "+data.getLong("Health")+" / "+data.getLong("Maximum")+"；建设值 "+String.format(java.util.Locale.ROOT,"%.1f",data.getLong("Health")/10.0),"修复 "+data.getLong("Repaired")+" · 新建 "+data.getLong("Constructed")+" · 拆除 "+data.getLong("Demolished"),"工资支出 "+data.getLong("Wages")+"银币；公共付款方余额 "+data.getLong("PublicSilver"),"待显示方块 "+data.getInt("Pending")+"；待清违建 "+data.getInt("Illegal"),data.getBoolean("Emergency")?"工坊全毁应急：已开放真实公共物资":"工坊应急：未触发",data.getString("Status")};for(String line:lines){g.drawString(font,font.plainSubstrByWidth(line,width-32),16,y,0xffccdacc);y+=19;}}
  else if(tab==1){g.drawString(font,"工坊需先记录含工作台/铁砧的房屋基准，并设置工人容量。",16,165,0xffccddcc);g.drawString(font,"在职工坊免自然损毁；全毁时工匠互救，物资照账扣除。",16,188,0xffccddcc);}
  else if(tab==2){g.drawString(font,"建筑名称",16,96,0xffddeedd);g.drawString(font,"X",16,152,0xffddeedd);g.drawString(font,"Y",149,152,0xffddeedd);g.drawString(font,"Z",269,152,0xffddeedd);}
  else{var resources=com.google.gson.JsonParser.parseString(data.getString("Resources")).getAsJsonObject();int stock=resources.has(resource)?resources.get(resource).getAsInt():0;g.drawString(font,"数量",16,99,0xffddeedd);g.drawString(font,"公仓库存 "+stock,224,99,0xffffdd99);g.drawString(font,"城市基价%",16,172,0xffddeedd);g.drawString(font,"财富比例%",16,199,0xffddeedd);int quote=Math.max(1,(int)Math.floor(5L*Integer.parseInt(cityPrice.getValue().matches("[0-9]{1,4}")?cityPrice.getValue():"100")*Integer.parseInt(wealth.getValue().matches("[0-9]{1,5}")?wealth.getValue():"100")/10000.0+.5));g.drawString(font,"面包示例：农村5银币 → 城市"+quote+"银币",16,231,0xffffdd99);g.drawString(font,"仅作财富价格效果预览，正式财富算法后续补充。",16,253,0xffbbccbb);}
  g.drawString(font,font.plainSubstrByWidth(local.isEmpty()?data.getString("Message"):local,width-32),16,height-44,0xffffbb77);super.render(g,mx,my,partial);}
 public boolean isPauseScreen(){return false;}public void renderBackground(GuiGraphics g,int x,int y,float partial){}
}
